def compute(vars):
    wireless = vars["v1"]
    high_speed_internet = vars["v2"]
    difference = wireless - high_speed_internet
    return {
        "value": difference,
        "trace": {
            "wireless_subscribers": wireless,
            "high_speed_internet_subscribers": high_speed_internet,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "subscribers"
            }
        }
    }
